namespace LocalSpt5Esp;
internal static class AiTeamControl {
 sealed record Team(LiveActorReference Anchor,IntPtr Pointer,int Id,string Text);
 sealed class LocalOriginal {internal LiveActorReference Actor=null!;internal BotsGroup? Group;internal string GroupId="";internal Il2CppSystem.Collections.Generic.IReadOnlyList<IPlayer>? Members;}
 static readonly List<Team> teams=new();static readonly HashSet<long> managed=new();static IntPtr world;static BotsGroup? joined;static LocalOriginal? original;static Team? destination;static string notice="",query="";static bool picking;static float nextRoster,nextEnforce,nextWarning;static Vector2 scroll,teamScroll;
 internal static void Initialize(Plugin plugin){plugin.Patches.Patch(typeof(LocalGame).GetMethod("Stop",new[]{typeof(string),typeof(ExitStatus),typeof(string),typeof(float)}),prefix:new HarmonyMethod(typeof(AiTeamControl),nameof(BeforeStop)));}
 [HarmonyPriority(Priority.Last)]
 static void BeforeStop(bool __runOriginal){if(__runOriginal)Leave(false);}
 internal static void Reset(){Leave(false);teams.Clear();managed.Clear();joined=null;original=null;world=IntPtr.Zero;destination=null;nextRoster=nextEnforce=0;picking=false;}
 internal static BotsGroup? Group(IPlayer? player){if(player==null)return null;if(original!=null&&player.ProfileId==original.Actor.Profile)return joined;return player.AIData?.BotOwner?.BotsGroup??player.TryCast<Player>()?.BotsGroup;}
 internal static bool Same(BotsGroup? from,IPlayer? target)=>from!=null&&Group(target) is {} to&&AiTeamRules.Same(world.ToInt64(),from.Pointer.ToInt64(),to.Pointer.ToInt64(),managed);
 internal static bool HasPlayer(BotsGroup group)=>original!=null&&joined?.Pointer==group.Pointer;
 internal static void Prefill(GameWorld current,IEnumerable<Player> selected){if(world!=IntPtr.Zero&&world!=current.Pointer)Reset();world=current.Pointer;var actor=selected.FirstOrDefault();if(actor?.AIData?.BotOwner?.BotsGroup is {} group)destination=new(new(current,actor),group.Pointer,group.Id,"队伍 #"+group.Id);picking=false;nextRoster=0;}
 static BotsGroup Destination(){var team=destination??throw new ArgumentException("请先选择目标队伍。");var anchor=team.Anchor.Resolve();var current=Singleton<GameWorld>.Instance;var group=anchor.AIData?.BotOwner?.BotsGroup;if(group==null||!AiTeamRules.MatchesDestination(team.Anchor.World.ToInt64(),team.Pointer.ToInt64(),current?.Pointer.ToInt64()??0,group.Pointer.ToInt64()))throw new ArgumentException("目标 AI 已更换队伍或离开，请重新选择目标队伍。");return group;}
 static Player Local(){var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current?.Pointer!=world||current.MainPlayer?.HealthController?.IsAlive!=true)throw new ArgumentException("需要当前战局存活的玩家。");return current.MainPlayer;}
 static List<Player> Members(BotsGroup group){var result=new List<Player>();var list=group._members;if(list!=null)for(int i=0;i<list.Count;i++){var actor=list[i]?.GetPlayer;if(actor?.HealthController?.IsAlive==true)result.Add(actor);}if(HasPlayer(group)&&Singleton<GameWorld>.Instance?.MainPlayer is {} local)result.Add(local);return result;}
 static void RefreshGroup(BotsGroup group,bool clearAll){var members=Members(group);string tag=members.Where(p=>!p.IsYourPlayer).Select(p=>p.Profile?.Info?.GroupId).FirstOrDefault(id=>!string.IsNullOrEmpty(id))??"assistant-"+world.ToInt64().ToString("X")+"-"+group.Id;var nativeMembers=new Il2CppSystem.Collections.Generic.List<IPlayer>();foreach(var actor in members){actor.SetGroup(group);if(actor.Profile?.Info is {} info)info.GroupId=tag;nativeMembers.Add(actor.Cast<IPlayer>());}var roster=nativeMembers.Cast<Il2CppSystem.Collections.Generic.IReadOnlyList<IPlayer>>();foreach(var actor in members){if(actor.AIData?.PlayerHostilityData is {} hostility)hostility.GroupMembers=roster;group.BotGroupHostility?.UpdatePlayerHostilityCollection(actor,new(BotHostilityStatus.Ally,"SPT Assistant team"));if(clearAll&&actor.AIData?.BotOwner is {} owner)foreach(var mate in members)if(mate.Pointer!=actor.Pointer)AiActorControl.Forget(owner,mate);}}
 static void JoinPlayer(){var player=Local();var target=Destination();if(HasPlayer(target)){notice="玩家已经在队伍 #"+target.Id+"。";return;}if(original!=null)Leave(false);original=new(){Actor=new(Singleton<GameWorld>.Instance,player),Group=player.BotsGroup,GroupId=player.Profile.Info.GroupId??"",Members=player.AIData?.PlayerHostilityData?.GroupMembers};joined=target;managed.Add(target.Pointer.ToInt64());try{player.SetGroup(target);RefreshGroup(target,true);if(player.BotsGroup?.Pointer!=target.Pointer||!target.Allies.ContainsKey(player))throw new InvalidOperationException("玩家队伍状态回读未确认。");notice="玩家已加入队伍 #"+target.Id+"。";FeatureToasts.Show(notice);nextRoster=0;}catch{Leave(false);throw;}}
 internal static void Leave(bool notify=true){var saved=original;var group=joined;if(saved==null)return;original=null;joined=null;try{var current=Singleton<GameWorld>.Instance;var player=current?.MainPlayer;if(current?.Pointer==saved.Actor.World&&player?.Pointer==saved.Actor.Pointer&&player.ProfileId==saved.Actor.Profile){if(saved.Group!=null)player.SetGroup(saved.Group);else player.BotsGroup=null!;player.Profile.Info.GroupId=saved.GroupId;if(player.AIData?.PlayerHostilityData is {} data)data.GroupMembers=saved.Members!;if(group?.BotGroupHostility is {} hostility){hostility.Allies.Remove(player);hostility.LastHostilityStatus.Remove(player.RaidId);hostility.OwnedGroupCalcActionNextFrame();}if(saved.Group!=null)saved.Group.BotGroupHostility?.OwnedGroupCalcActionNextFrame();}notice="玩家已退出自定义队伍。";if(notify)FeatureToasts.Show(notice);}catch(Exception e){Plugin.Self.Log.LogWarning("Player leave AI team: "+e.Message);}nextRoster=0;}
 static void Move(Player actor,BotsGroup target){if(actor.IsYourPlayer||!actor.IsAI)throw new ArgumentException("只能转移当前战局 AI。");var owner=actor.AIData?.BotOwner??throw new ArgumentException("AI 控制器暂不可用。");var from=owner.BotsGroup??throw new ArgumentException("AI 没有所属队伍。");if(from.Pointer==target.Pointer)return;var oldMemory=owner.Memory?._botsGroup;string oldTag=actor.Profile.Info.GroupId??"";try{actor.HandsController?.TryCast<Player.FirearmController>()?.SetTriggerPressed(false);target.AddMember(owner,false);if(!target.Contains(owner))throw new InvalidOperationException("目标队伍未接受这名 AI。");if(from.Contains(owner))from.RemoveMember(owner);owner.BotsGroup=target;actor.SetGroup(target);if(owner.Memory!=null)owner.Memory._botsGroup=target;if(owner.BotsGroup?.Pointer!=target.Pointer||actor.BotsGroup?.Pointer!=target.Pointer||!target.Contains(owner)||from.Contains(owner))throw new InvalidOperationException("AI 队伍状态回读不一致。");if(from.BotGroupHostility is {} oldHostility){oldHostility.Allies.Remove(actor);oldHostility.LastHostilityStatus.Remove(actor.RaidId);oldHostility.OwnedGroupCalcActionNextFrame();}}
  catch{try{if(target.Contains(owner))target.RemoveMember(owner);if(!from.Contains(owner))from.AddMember(owner,false);owner.BotsGroup=from;actor.SetGroup(from);actor.Profile.Info.GroupId=oldTag;if(owner.Memory!=null)owner.Memory._botsGroup=oldMemory??from;}catch(Exception e){Plugin.Self.Log.LogWarning("AI membership rollback: "+e.Message);}throw;}}
 static void Merge(Func<Player[]> selected,bool useFirst){var actors=selected();if(actors.Length==0)throw new ArgumentException("请先在 AI 列表选择来源 AI。");var target=useFirst?actors[0].AIData?.BotOwner?.BotsGroup??throw new ArgumentException("第一名 AI 没有队伍。"):Destination();if(useFirst&&actors.Length<2)throw new ArgumentException("至少选择两名 AI 后使用一键组队。");var snapshots=actors.Select(actor=>(Actor:actor,Group:actor.AIData?.BotOwner?.BotsGroup??throw new ArgumentException("来源 AI 没有队伍。"),Tag:actor.Profile.Info.GroupId)).ToArray();var moved=new List<(Player Actor,BotsGroup Group,string Tag)>();try{foreach(var entry in snapshots){if(entry.Group.Pointer==target.Pointer)continue;moved.Add(entry);Move(entry.Actor,target);}managed.Add(target.Pointer.ToInt64());RefreshGroup(target,true);foreach(var old in snapshots.Select(e=>e.Group).Where(g=>g.Pointer!=target.Pointer).GroupBy(g=>g.Pointer).Select(g=>g.First()))if(old.MembersCount>0)RefreshGroup(old,true);notice="已将 "+actors.Length+" 名所选 AI 编入队伍 #"+target.Id+"。";FeatureToasts.Show(notice);nextRoster=0;}catch{foreach(var entry in moved.AsEnumerable().Reverse())try{Move(entry.Actor,entry.Group);entry.Actor.Profile.Info.GroupId=entry.Tag;}catch(Exception e){Plugin.Self.Log.LogWarning("AI team rollback: "+e.Message);}throw;}}
 internal static void Tick(GameWorld? current){if(current==null){if(world!=IntPtr.Zero)Reset();return;}if(world!=IntPtr.Zero&&world!=current.Pointer){Reset();return;}if(managed.Count==0||Time.unscaledTime<nextEnforce)return;nextEnforce=Time.unscaledTime+1;try{var all=current.AllAlivePlayersList;if(all==null)return;foreach(var actor in all){var owner=actor?.AIData?.BotOwner;var group=owner?.BotsGroup;if(group==null||!managed.Contains(group.Pointer.ToInt64()))continue;var goal=owner!.Memory?.GoalEnemy?.Person;if(goal!=null&&Same(group,goal))AiActorControl.Forget(owner,goal);if(HasPlayer(group)&&current.MainPlayer is {} local){if(!group.Allies.ContainsKey(local))group.BotGroupHostility?.UpdatePlayerHostilityCollection(local,new(BotHostilityStatus.Ally,"SPT Assistant team"));AiActorControl.Forget(owner,local);}}}catch(Exception e){if(Time.unscaledTime>=nextWarning){nextWarning=Time.unscaledTime+20;Plugin.Self.Log.LogWarning("AI team update: "+e.Message);}}}
 static void Roster(){var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current==null){teams.Clear();return;}if(Time.unscaledTime<nextRoster)return;nextRoster=Time.unscaledTime+1;teams.Clear();var all=current.AllAlivePlayersList;if(all==null)return;var seen=new HashSet<IntPtr>();for(int i=0;i<all.Count;i++){var actor=all[i];var group=actor?.AIData?.BotOwner?.BotsGroup;if(actor?.HealthController?.IsAlive!=true||group==null||!seen.Add(group.Pointer))continue;teams.Add(new(new(current,actor),group.Pointer,group.Id,"队伍 #"+group.Id+" · "+group.MembersCount+" AI"+(HasPlayer(group)?" + 玩家":"")+" · "+(actor.Profile?.Nickname??"AI")));}}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);Plugin.Self.Log.LogWarning("AI teams: "+e.Message);}}
 internal static void Draw(Rect rect,Func<Player[]> selected){Roster();scroll=GUI.BeginScrollView(rect,scroll,new Rect(0,0,rect.width-20,picking?780:560));float x=8,y=8,w=rect.width-38;InterfaceMenu.Label(new Rect(x,y,w,30),"玩家与 AI 组队",InterfaceMenu.Accent,20);y+=44;InterfaceMenu.Label(new Rect(x,y,w,30),joined==null?"玩家尚未加入 AI 队伍":"玩家当前：队伍 #"+joined.Id+" · "+joined.MembersCount+" 名 AI",null,14);y+=44;if(InterfaceMenu.Button(new Rect(x,y,w,36),"目标："+(destination?.Text??"请选择队伍")+"  ›"))picking=!picking;y+=48;
  if(picking){query=InterfaceMenu.Field(new Rect(x,y,w,32),query);y+=44;var rows=teams.Where(t=>t.Text.Contains(query,StringComparison.OrdinalIgnoreCase)).ToArray();teamScroll=GUI.BeginScrollView(new Rect(x,y,w,168),teamScroll,new Rect(0,0,w-20,Math.Max(167,rows.Length*44)));for(int i=0;i<rows.Length;i++)if(InterfaceMenu.Button(new Rect(0,i*44,w-26,36),rows[i].Text,destination?.Pointer==rows[i].Pointer)){destination=rows[i];picking=false;}GUI.EndScrollView();y+=184;}
  float half=(w-12)/2;bool old=GUI.enabled;GUI.enabled=old&&destination!=null;if(InterfaceMenu.Button(new Rect(x,y,half,38),"玩家加入目标队伍"))Action(JoinPlayer);GUI.enabled=old&&original!=null;if(InterfaceMenu.Button(new Rect(x+half+12,y,half,38),"玩家退出队伍"))Leave();GUI.enabled=old;y+=58;InterfaceMenu.Label(new Rect(x,y,w,28),"将 AI 编入同一队伍",InterfaceMenu.Accent,17);y+=40;if(InterfaceMenu.Button(new Rect(x,y,w,38),"所选 AI 一键组队（加入第一名的队伍）"))Action(()=>Merge(selected,true));y+=52;GUI.enabled=old&&destination!=null;if(InterfaceMenu.Button(new Rect(x,y,w,38),"将所选 AI 编入目标队伍"))Action(()=>Merge(selected,false));GUI.enabled=old;y+=56;InterfaceMenu.Paragraph(new Rect(x,y,w,68),"在 AI 列表多选后进入本页。加入已有队伍会合并队伍成员；玩家也可加入同一队，退出后恢复原队伍。",null,13);y+=82;InterfaceMenu.Paragraph(new Rect(x,y,w,72),notice,InterfaceMenu.Accent,13);GUI.EndScrollView();}
}
